Record Contact
  Define name, phone As String;
  Define mes As Integer;
EndRecord

Algorithm Buscar
  Define contacts As Vector<Contact> <- vector();
  Define name, phone As String;
  Define mes As Integer;
  For i <- 1 To 4 Do
    Read name;
    Read phone;
    Read mes;
    contacts.append(Contact(name, phone, mes));
  EndFor
  Read name;
  Define found As String <- "Not found";
  For Each contact In contacts Do
    If contact.name = name And found = "Not found" Then
      found <- contact.phone;
    EndIf
  EndFor
  Write found;
EndAlgorithm
